forces
{
	type				forces;
	functionObjectLibs	("libforces.so");
	enabled				true;
	outputControl		${1:timeStep};
	outputInterval		${2:1};
	patches				(${3});
	log					${4:true};
	CofR				(${0:0 0 0});
}

${1:p}
{
	solver          GAMG;
	tolerance       1e-${2:6};
	relTol          ${0:0.0};
	smoother        GaussSeidel;
	cacheAgglomeration true;
	nCellsInCoarsestLevel 10;
	agglomerator    faceAreaPair;
	mergeLevels     1;
}

${1:U}
{
	solver          PBiCG;
	preconditioner  DILU;
	tolerance       1e-${2:6};
	relTol          ${0:0.0};
}
